-- Seed: About page (تعرف علي)
insert into public.page_content (page, section_key, content_ar, content_en) values
  ('about', 'about_intro_1', 'مدونتي والتي أدون بها بعض من تجاربي ومحطاتي في رحلة آمل أن تلهمك.', 'My blog, where I write about some of my experiences and milestones on a journey I hope will inspire you.'),
  ('about', 'about_intro_2', 'اسمي بدر بن حمود البدر، مهتم بتمكين الشباب وقيادة التحول وريادة الأعمال بالإضافة إلى توجيه المؤسسات ومساعدتها على إيجاد حلول مستدامة.', 'My name is Badr bin Hamoud Al-Badr. I''m passionate about youth empowerment, leading transformation, and entrepreneurship, as well as advising organizations and helping them find sustainable solutions.'),
  ('about', 'about_intro_3', 'بالنسبة لي، المواقف الصعبة هي مصدر تحفيز فأنا أجد متعتي بالعمل في فترات عدم اليقين، وأوقات التغيير السريع وأجدها فرصة لتحليل الواقع وتصور المستقبل وحل المشكلات.', 'For me, difficult situations are a source of motivation — I enjoy working through periods of uncertainty and rapid change, seeing them as opportunities to analyze reality, envision the future, and solve problems.'),
  ('about', 'career_items', '[{"title": "الرئيس التنفيذي لمؤسسة محمد بن سلمان \"مسك\" 2019 – الآن", "body": "عُينت لقيادة مؤسسة محمد بن سلمان \"مسك\" التي تهدف إلى تمكين الشباب. عملت على إعادة توجيه الاستراتيجية للتركيز على تطوير الشباب وتمكينهم، بوضع النتائج بعيدة المدى والأهداف السنوية للمؤسسة.\nوأود التنويه هنا إلى أن آرائي في المدونة لا تمثل بالضرورة آراء المؤسسة."}, {"title": "الرئيس التنفيذي لشركة دور للضيافة 2012 – 2019", "body": "كنت ولمدة سبع سنوات رئيسًا تنفيذيًا لشركة دور للضيافة. قدت تحول الشركة من الشركة السعودية للفنادق والمنتجعات السياحية إلى شركة دور في حلتها الجديدة والمعاصرة في رحلة استراتيجية بدأت بصياغة الرؤية ووضع الاستراتيجية انطلاقًا للتنفيذ مع تعديل المسار وفقًا لما يمليه السوق."}, {"title": "الرئيس التنفيذي لشركة سيسكو – آسيا و إفريقيا 2009 – 2011", "body": ""}, {"title": "الرئيس التنفيذي لشركة سيسكو – السعودية 2007 – 2009", "body": ""}, {"title": "المدير العام لشركة سيسكو 2004 – 2009", "body": "توليت قيادة شركة سيسكو (الشركة العالمية المختصة في الشبكات والاتصالات) وتوسعها في المملكة العربية السعودية. وطورت أعمال الشركة في مجال المدن الذكية في منطقة الشرق الأوسط وشمال أفريقيا، وحزت أثناء عملي على جائزتي أفضل مدير عام في المنطقة وأفضل بيئة عمل."}, {"title": "الرئيس التنفيذي وعضو مجلس إدارة شركة رقمية 2003 – 2004", "body": ""}, {"title": "الرئيس التنفيذي لشركة أول نت 2002 – 2002", "body": "بعد أن كنت عضوًا في فريق عمل مشروع الإنترنت الذي كان مسؤولاً عن تنظيم وتشغيل خدمة الإنترنت في بداية عملها في المملكة في أواخر التسعينيات، شغلت منصب الرئيس التنفيذي لشركة أول نت (جزء من شركة الاتصالات السعودية STC حاليًا)."}, {"title": "الرئيس التنفيذي لشركة العالمية للاتصالات والإنترنت 1999 – 2002", "body": ""}]', '[{"title": "CEO of the Mohammed bin Salman Foundation \"Misk\" 2019 – Present", "body": "Appointed to lead the Misk Foundation, which aims to empower youth. Refocused the strategy on youth development and empowerment, setting long-term outcomes and annual goals for the foundation.\nNote: my views on this blog do not necessarily represent those of the foundation."}, {"title": "CEO of Dur Hospitality 2012 – 2019", "body": "For seven years I served as CEO of Dur Hospitality. I led the company''s transformation from the Saudi Hotels & Resorts Company into the new, modern Dur, in a strategic journey that began with shaping the vision and strategy, then adjusting course as the market required."}, {"title": "CEO of Cisco – Asia & Africa 2009 – 2011", "body": ""}, {"title": "CEO of Cisco – Saudi Arabia 2007 – 2009", "body": ""}, {"title": "General Manager of Cisco 2004 – 2009", "body": "Led Cisco (the global networking and communications company) and its expansion in Saudi Arabia. Grew the company''s smart-cities business across the Middle East and North Africa, and received the Best General Manager and Best Workplace awards during my tenure."}, {"title": "CEO & Board Member of a Digital Company 2003 – 2004", "body": ""}, {"title": "CEO of Awalnet 2002 – 2002", "body": "After being part of the internet project team responsible for organizing and operating internet service in the Kingdom in the late 1990s, I served as CEO of Awalnet (now part of Saudi Telecom Company, STC)."}, {"title": "CEO of Al-Alamiyah Telecom & Internet Company 1999 – 2002", "body": ""}]'),
  ('about', 'qualifications', '[{"text": "بكالوريوس في تخصص علوم الحاسب مع مرتبة الشرف الأولى - جامعة الملك فهد للبترول والمعادن بالظهران"}, {"text": "درجتي الماجستير والدكتوراه في تخصص هندسة علوم الحاسب - جامعة واشنطن"}]', '[{"text": "B.Sc. in Computer Science, First Class Honors — King Fahd University of Petroleum and Minerals, Dhahran"}, {"text": "M.Sc. and Ph.D. in Computer Science Engineering — University of Washington"}]'),
  ('about', 'hobbies_text', 'خارج مكتبي، أمارس هوايتي بنفس الشغف الذي أمارس به عملي فالرياضة والاستكشاف جزء مهم من حياتي واعتبرها من أهم مكونات شخصيتي القيادية. أحب التمرين والسفر بالدراجة الهوائية، وأشارككم تفاصيل من بعض رحلاتي في المدونة. وعدت مؤخرًا لهواية قديمة وهي التصوير وأشارككم هنا بعض من لقطاتي (غالب صور الموقع من تصويري). كما أنني شغوف بنشر المعرفة عبر شبكات التواصل الاجتماعي وأحاضر في الفعاليات المتعلقة بتخصصي وخبراتي.', 'Outside the office, I pursue my hobbies with the same passion I bring to my work — sports and exploration are an important part of my life and, I believe, a key part of my leadership personality. I enjoy working out and cycling trips, and I share details from some of my journeys on the blog. I''ve also recently returned to an old hobby, photography, and share some of my shots here (most of the site''s photos are my own). I''m also passionate about sharing knowledge on social media and speak at events related to my field and experience.')
on conflict (page, section_key) do nothing;

-- Seed: About page awards paragraph
insert into public.page_content (page, section_key, content_ar, content_en) values
  ('about', 'awards_text', 'نلت جوائزًا عديدة خلال مسيرتي القيادية، إذ صنفت ضمن: أفضل 100 رئيس تنفيذي في المنطقة، وضمن أقوى 20 مديرًا تنفيذيًا في مجال الضيافة بالمنطقة، ولثلاث مرات نالت شركات قدتها جائزة أفضل بيئة عمل في المملكة.', 'I received numerous awards during my leadership career, including being named among the Top 100 CEOs in the region, one of the Top 20 hospitality executives in the region, and companies I led won the Best Workplace Award in the Kingdom three times.')
on conflict (page, section_key) do nothing;
